const scan = $('Scan Repository').item.json;
const agent = $json;
const input = $('Mimir Webhook').item.json.body ?? {};
const candidates = new Map();

function touch(path, score, reason) {
  if (!path) return;
  const current = candidates.get(path) ?? { path, score: 0, reasons: [] };
  current.score += score;
  if (!current.reasons.includes(reason)) current.reasons.push(reason);
  candidates.set(path, current);
}

for (const hotspot of scan.hotspots ?? []) {
  touch(hotspot.path, Math.min(Number(hotspot.touches ?? 0), 20) * 3, `changed ${hotspot.touches} times in recent history`);
}
for (const file of scan.largest_files ?? []) {
  if ((file.lines ?? 0) < 250) continue;
  touch(file.path, Math.min(Math.ceil(file.lines / 100), 15) * 2, `${file.lines} lines`);
}
for (const finding of scan.findings ?? []) {
  if (finding.severity === 'low') continue;
  const weight = finding.severity === 'critical' ? 12 : finding.severity === 'high' ? 8 : 4;
  touch(finding.path, weight, `${finding.severity} ${finding.category}: ${finding.rule}`);
}

const ranked = [...candidates.values()]
  .sort((a, b) => b.score - a.score)
  .slice(0, 20)
  .map((item, index) => ({ rank: index + 1, ...item }));

return [{
  json: {
    status: 'completed',
    workflow: 'refactor-analysis',
    run_id: String($execution.id),
    contract_version: 3,
    repository: scan.repository,
    requested_ref: scan.requested_ref,
    commit: scan.commit,
    objective: input.objective ?? 'maintainability',
    target: input.target ?? 'repository',
    summary: {
      analyzed_files: scan.inventory?.analyzed_files ?? 0,
      candidate_count: ranked.length,
      findings: scan.findings_summary ?? {}
    },
    deterministic_candidates: ranked,
    agent_analysis: {
      configured: Boolean(agent.configured),
      mode: agent.mode ?? 'unknown',
      model: agent.model ?? null,
      latency_ms: agent.latency_ms ?? null,
      analysis: agent.analysis ?? null,
      error: agent.error ?? null,
      usage: agent.usage ?? null
    },
    hotspots: (scan.hotspots ?? []).slice(0, 20),
    largest_files: (scan.largest_files ?? []).slice(0, 20),
    constraints: input.constraints ?? []
  }
}];
